#!/usr/bin/env bash
# Third Hustle hourly tracker - one-step installer for the Lightsail server.
# Run:  curl -4 -sSL <link> -o install.sh && bash install.sh
set -euo pipefail
REPO="$HOME/Opty-Data"; HUSTLE="$HOME/hustle"; PY="$(command -v python3)"
say(){ printf '\n\033[1m%s\033[0m\n' "$*"; }
[ -n "$PY" ] || { echo "python3 is not installed. Run: sudo apt-get install -y python3"; exit 1; }
command -v git >/dev/null || sudo apt-get install -y git
mkdir -p "$HUSTLE"

say "1/6  Your keys (typing is hidden; press Enter to keep a saved value)"
[ -f "$HUSTLE/.env" ] && . "$HUSTLE/.env" || true
ask(){ local v; read -r -s -p "$1: " v </dev/tty; echo; printf '%s' "${v:-$2}"; }
ALPACA_KEY="$(ask 'Alpaca API key ID' "${ALPACA_KEY:-}")"
ALPACA_SECRET="$(ask 'Alpaca secret key' "${ALPACA_SECRET:-}")"
GH_TOKEN_IN="$(ask 'GitHub token (Contents read/write on Opty-Data)' "${GH_TOKEN:-}")"
[ -n "$ALPACA_KEY" ] && [ -n "$ALPACA_SECRET" ] && [ -n "$GH_TOKEN_IN" ] || { echo "All three are needed."; exit 1; }
cat > "$HUSTLE/.env" <<ENV
ALPACA_KEY=$ALPACA_KEY
ALPACA_SECRET=$ALPACA_SECRET
GH_TOKEN=$GH_TOKEN_IN
OPTIONS_FEED=${OPTIONS_FEED:-opra}
STOCK_FEED=${STOCK_FEED:-sip}
REPO_DIR=$REPO
NTFY_TOPIC=opty-mm-2nrkd8ap75hj4i5h
PUSH=1
ENV
chmod 600 "$HUSTLE/.env"

say "2/6  Getting the Opty-Data repo"
URL="https://nohs10:${GH_TOKEN_IN}@github.com/nohs10/Opty-Data.git"
if [ -d "$REPO/.git" ]; then git -C "$REPO" remote set-url origin "$URL"; git -C "$REPO" pull --rebase -q;
else git clone -q "$URL" "$REPO"; fi
git -C "$REPO" config user.name "Opty Server"; git -C "$REPO" config user.email "server@opty.local"

say "3/6  Installing the tracker and the website update"
mkdir -p "$REPO/tools"
echo "" | base64 -d > "$REPO/tools/hustle_hourly.py"
echo "" | base64 -d > "$REPO/spread-desk/opty-spread-desk.js"
echo "" | base64 -d > "$HUSTLE/data.fixed.json"
if "$PY" -c "import json,sys;a=json.load(open('$REPO/spread-desk/data.json'));b=json.load(open('$HUSTLE/data.fixed.json'));sys.exit(0 if a.get('date')==b.get('date') else 1)"; then
  cp "$HUSTLE/data.fixed.json" "$REPO/spread-desk/data.json"; echo "   Friday card fixed for this week."
else echo "   data.json is already newer; left as is."; fi
"$PY" -m py_compile "$REPO/tools/hustle_hourly.py"

say "4/6  Testing with live Alpaca data (nothing is published)"
if ! "$PY" "$REPO/tools/hustle_hourly.py" --force --dry > "$HUSTLE/test.log" 2>&1; then
  if grep -qiE "403|subscription|forbidden" "$HUSTLE/test.log"; then
    echo "   Your plan doesn't include OPRA/SIP; switching to the free indicative/IEX feeds."
    sed -i 's/^OPTIONS_FEED=.*/OPTIONS_FEED=indicative/; s/^STOCK_FEED=.*/STOCK_FEED=iex/' "$HUSTLE/.env"
    "$PY" "$REPO/tools/hustle_hourly.py" --force --dry > "$HUSTLE/test.log" 2>&1 || { tail -5 "$HUSTLE/test.log"; echo "Test failed. Check your Alpaca keys and run again."; exit 1; }
  else tail -5 "$HUSTLE/test.log"; echo "Test failed. Check your Alpaca keys and run again."; exit 1; fi
fi
grep -m1 "wrote hourly.json" "$HUSTLE/test.log" || true
git -C "$REPO" checkout -q -- spread-desk/hourly.json 2>/dev/null || rm -f "$REPO/spread-desk/hourly.json"

say "5/6  Publishing the website update"
git -C "$REPO" add tools/hustle_hourly.py spread-desk/opty-spread-desk.js spread-desk/data.json
if [ -n "$(git -C "$REPO" status --porcelain tools spread-desk)" ]; then
  git -C "$REPO" commit -q -m "Hourly tracker: server script, site shows hourly checks, Friday sit-out"
  git -C "$REPO" push -q || { git -C "$REPO" pull --rebase -q; git -C "$REPO" push -q; }
  echo "   Pushed $(git -C "$REPO" rev-parse --short HEAD)"
else echo "   Already up to date."; fi

say "6/6  Scheduling: every hour at :35, Mon-Fri (the script only works 10:35 AM-3:35 PM ET)"
LINE="35 * * * 1-5 $PY $REPO/tools/hustle_hourly.py >> $HUSTLE/hourly.log 2>&1"
( crontab -l 2>/dev/null | grep -v "hustle_hourly.py"; echo "$LINE" ) | crontab -
crontab -l | grep hustle_hourly
curl -4 -sS -X POST "https://ntfy.sh/opty-mm-2nrkd8ap75hj4i5h" -H "Title: Third Hustle hourly tracker installed" -d "Runs every hour 10:35 AM-3:35 PM ET on market days. Alerts only when odds get worse." >/dev/null || true
say "7/7  Claude on this server (so Claude can manage your jobs from the Claude app)"
command -v tmux >/dev/null || sudo apt-get install -y tmux
if ! command -v claude >/dev/null && [ ! -x "$HOME/.local/bin/claude" ]; then curl -fsSL https://claude.ai/install.sh | bash; fi
grep -q '.local/bin' "$HOME/.bashrc" || echo 'export PATH="$HOME/.local/bin:$PATH"' >> "$HOME/.bashrc"
mkdir -p "$HOME/ops"
cat > "$HOME/ops/CLAUDE.md" <<'MD'
# Opty server ops
You run on the user's Lightsail server (Ubuntu, user ubuntu) as his operator. He asks in plain English; you edit, add or remove his jobs.
- Jobs are scheduled in crontab (crontab -l). Show the current job list before and after any change.
- Third Hustle hourly tracker: ~/Opty-Data/tools/hustle_hourly.py, settings ~/hustle/.env (never print the secrets), log ~/hustle/hourly.log, cron "35 * * * 1-5". It writes spread-desk/hourly.json in ~/Opty-Data and pushes it (the public website reads it).
- Test any job change with a dry run first (hustle_hourly.py --force --dry). Never force-push, never delete the repo, never place trades.
- IPv6 is broken on this box: use curl -4. Phone alerts: ntfy topic in ~/hustle/.env.
MD
say "Done. First check: next market day at 10:35 AM ET. Log: $HUSTLE/hourly.log"
echo "To connect Claude: run  tmux new -s claude  then  cd ~/ops && claude  (log in), exit, then  claude remote-control"
